const input = $json.body ?? $json;
const contentId = String(input.contentId ?? '').trim();
const title = String(input.title ?? '').trim();
const rawUrl = String(input.url ?? '').trim();
const suppliedContent = String(input.content ?? '').trim();
if (!contentId) throw new Error('contentId is required');
if (!title) throw new Error('title is required');
if (!rawUrl && !suppliedContent) throw new Error('Provide url or content');
let url = '';
if (rawUrl) {
  const parsed = new URL(rawUrl);
  if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error('Only http/https URLs are accepted');
  url = parsed.toString();
}
if (suppliedContent.length > 100000) throw new Error('content exceeds 100000 characters');
const host = url ? new URL(url).hostname.toLowerCase() : '';
const platform = host.includes('youtube.com') || host === 'youtu.be' ? 'youtube' : host.includes('linkedin.com') ? 'linkedin' : host.includes('facebook.com') || host === 'fb.watch' ? 'facebook' : host.includes('instagram.com') ? 'instagram' : host.includes('threads.net') ? 'threads' : host.includes('tiktok.com') ? 'tiktok' : host === 'x.com' || host.endsWith('.x.com') || host.includes('twitter.com') ? 'x' : 'web';
const requestId = `${contentId}-${Date.now()}`;
return [{ json: { contentId, title, requestId, url, platform, suppliedContent, notes: String(input.notes ?? '').slice(0, 5000), submittedAt: new Date().toISOString() } }];

const original = $('Validate and Normalize').item.json;
const extracted = original.suppliedContent || String($json.data ?? $json.body ?? $json ?? '');
if (!extracted || extracted === '[object Object]') throw new Error('Could not extract content; submit content explicitly');
return [{ json: { ...original, sourceContent: extracted.slice(0, 100000) } }];

