const source = $('Prepare Source').item.json;
const response = $json;
const text = response.output_text ?? response.output?.flatMap(o => o.content ?? []).find(c => c.type === 'output_text')?.text;
if (!text) throw new Error('OpenAI returned no output text');
let draft;
try { draft = JSON.parse(text); } catch { throw new Error('OpenAI output was not valid JSON'); }
return [{ json: { contentId: source.contentId, title: source.title, requestId: source.requestId, sourceUrl: source.url, platform: source.platform, submittedAt: source.submittedAt, status: 'pending_review', message: 'Draft generated successfully and sent to the review queue.', draft } }];

